krpano.action:
set(skin_settings.thumbs,         false);
set(skin_settings.thumbs_opened,  false);
set(skin_settings.thumbs_text,    false);
set(skin_settings.title,          false);
set(skin_settings.autotour,       false);
set(skin_settings.controlbar_overlap, 0);


set(layer[skin_layer].visible,            false);
set(layer[skin_btn_thumbs].visible,       false);
set(layer[skin_btn_prev].visible,         false);
set(layer[skin_btn_next].visible,         false);
set(layer[skin_btn_prev_fs].visible,      false);
set(layer[skin_btn_next_fs].visible,      false);
set(layer[skin_btn_hide].visible,         false);
set(layer[skin_btn_show].visible,         false);
set(layer[skin_scroll_window].visible,    false);
set(layer[skin_splitter_bottom].visible,  false);
set(layer[skin_control_bar].visible,      false);


if(layer[skin_logo_name],
    set(layer[skin_logo_name].enabled,   true);
    set(layer[skin_logo_name].bgcapture, true);
    set(layer[skin_logo_name].zorder,    150);
    set(layer[skin_logo_name].x,         10);
    set(layer[skin_logo_name].y,         5);
    set(layer[skin_logo_name].scale,     0.30);
    set(layer[skin_logo_name].onclick,   topmenu_logo_click(););
    set(layer[skin_logo_name].visible,   true);
);

topmenu_update_layout();
pano_browser_init_late();
update_zoom_indicator();

copy(_fov, view.fov);
clamp(_fov, 30, 150);
calc(_ratio, (_fov - 30) / 120);
calc(_h, 104 - _ratio * 96);
set(layer[zoom_indicator_fill].height, get(_h));

delayedcall(1.5,
    if(global.pano_browser_current_cat == null,
        pano_browser_build_from_current();
    );
);

if(global.pb_busy == true, break(); );
stopdelayedcall(pb_check);
delayedcall(pb_check, 0.1, pano_browser_check_category_change());

if(global.pb_busy == true, break(); );
set(global.pb_busy, true);

if(xml.scene == null, set(global.pb_busy, false); break(); );

copy(_nowcat, scene[get(xml.scene)].category);
if(_nowcat == null,
    get_scene_category(get(xml.scene));
    copy(_nowcat, global.scene_cat_result);
);

if(_nowcat != null AND _nowcat == global.pano_browser_current_cat,
    pano_browser_sync_active();
    set(global.pb_busy, false);
    break();
);

pano_browser_build_from_current();
set(global.pb_busy, false);

if(scene.count == 0, break(); );

copy(_cat, scene[get(xml.scene)].category);
if(_cat == null,
    get_scene_category(get(xml.scene));
    copy(_cat, global.scene_cat_result);
);

copy(global.pano_browser_current_cat, get(_cat));
pano_browser_build(get(_cat));


copy(_prev, global.pano_items_count);
if(_prev == null, set(_prev, 0); );
for(set(_n, 0), _n LT _prev, inc(_n),
    calc(_old,  'pano_item_'  + _n);
    calc(_oldt, 'pano_title_' + _n);
    if(layer[get(_old)],  removelayer(get(_old), true); );
    if(layer[get(_oldt)], removelayer(get(_oldt), true); );
);

def(global.pano_thumbarray, array);
set(_pos, 0);

for(set(i, 0), i LT scene.count, inc(i),

    copy(_scat, scene[get(i)].category);
    if(_scat == null,
        get_scene_category(get(scene[get(i)].name));
        copy(_scat, global.scene_cat_result);
    );
    if((cat == null OR _scat == get(cat))
    AND scene[get(i)].thumburl != null
    AND scene[get(i)].skipthumb != true,
        set(global.pano_thumbarray[get(_pos)], get(scene[get(i)]));
        inc(_pos);
    );
);

if(_pos == 0 AND cat != null,
    pano_browser_build(null);
    break();
);

for(set(i, 0), i LT _pos, inc(i),
    copy(_s, global.pano_thumbarray[get(i)]);
    calc(_item,  'pano_item_'  + i);
    calc(_title, 'pano_title_' + i);
    calc(_py,    i * 66 + 6);

    addlayer(get(_item));
    set(layer[get(_item)].url,          get(_s.thumburl));
    set(layer[get(_item)].keep,         true);
    set(layer[get(_item)].parent,       'pano_browser_scroll');
    set(layer[get(_item)].align,        'lefttop');
    set(layer[get(_item)].x,            6);
    calc(layer[get(_item)].y, _py);
    set(layer[get(_item)].width,        178);
    set(layer[get(_item)].height,       60);
    set(layer[get(_item)].linkedscene,  get(_s.name));
    set(layer[get(_item)].bgcolor,      0x2D3E50);
    set(layer[get(_item)].bgalpha,      1.0);
    set(layer[get(_item)].bgborder,     '1 0x3A4A45 1');
    set(layer[get(_item)].bgroundedge,  6);
    set(layer[get(_item)].bgcapture,    true);
    set(layer[get(_item)].onclick,      'pano_browser_load(get(linkedscene));');
    set(layer[get(_item)].onover,       'tween(bgalpha, 0.85, 0.12);');
    set(layer[get(_item)].onout,        'tween(bgalpha, 1.0, 0.12);');

    addlayer(get(_title));
    set(layer[get(_title)].type,     'text');
    set(layer[get(_title)].parent,   get(_item));
    set(layer[get(_title)].align,    'bottom');
    set(layer[get(_title)].width,    178);
    set(layer[get(_title)].height,   20);
    set(layer[get(_title)].bgcolor,  0x0F1614);
    set(layer[get(_title)].bgalpha,  0.85);
    set(layer[get(_title)].css,
        'color:#F5B400; font-family:Arial; font-size:11px; font-weight:bold; text-align:center;');
    set(layer[get(_title)].vcenter,  true);
    set(layer[get(_title)].enabled,  false);
    set(layer[get(_title)].html,     get(_s.title));
);

calc(_total, _pos * 66 + 6);
set(layer[pano_browser_scroll].height, get(_total));
copy(global.pano_items_count, _pos);


set(global.pb_active_item, null);
pano_browser_sync_active();


stopdelayedcall(pb_scroll_init);
stopdelayedcall(pb_scroll_active);
delayedcall(pb_scroll_active, 0.25, pano_browser_scroll_to_active());

copy(_active, xml.scene);
copy(_count, global.pano_items_count);
if(_count == null, set(_count, 0); );

for(set(i, 0), i LT _count, inc(i),
    calc(_it, 'pano_item_' + i);
    if(layer[get(_it)],
        if(layer[get(_it)].linkedscene == get(_active),
            copy(_y, layer[get(_it)].y);
            calc(_ycenter, _y + 30);
            layer[pano_browser_scroll].scrolltocenter(96, get(_ycenter), 0.3);
            break();
        );
    );
);

if(layer[pano_browser].state == 'open',
    set(layer[pano_browser].state, 'closed');
    tween(layer[pano_browser].alpha, 0, 0.3, easeInQuad,
        set(layer[pano_browser].visible, false));
    set(layer[pano_browser_toggle].html, '▸');
,
    set(layer[pano_browser].state, 'open');
    set(layer[pano_browser].visible, true);
    set(layer[pano_browser].alpha, 0);
    tween(layer[pano_browser].alpha, 1, 0.3, easeOutQuad);
    set(layer[pano_browser_toggle].html, '◂');
    delayedcall(0.35, pano_browser_scroll_to_active(););
);

if(%1 == null OR %1 == '', break(); );
if(scene[%1] == null, break(); );
loadscene(%1, null, MERGE, BLEND(0.5, easeOutQuad));

copy(_active, xml.scene);


if(global.pb_active_item != null,
    if(layer[get(global.pb_active_item)],
        set(layer[get(global.pb_active_item)].bgborder, '1 0x3A4A45 1');
    );
);

copy(_count, global.pano_items_count);
if(_count == null, set(_count, 0); );


for(set(i, 0), i LT _count, inc(i),
    calc(_it, 'pano_item_' + i);
    if(layer[get(_it)],
        if(layer[get(_it)].linkedscene == get(_active),
            set(layer[get(_it)].bgborder, '3 0xF5B400 1.0');
            copy(global.pb_active_item, get(_it));
            break();
        );
    );
);

set(_is_mobile, false);
if(device.mobile OR stagewidth LT 760, set(_is_mobile, true); );

if(_is_mobile,
    set(layer[top_menu_bar].visible, false);
    set(layer[top_menu_mobile_btn].visible, true);
    topmenu_close_all();
    if(layer[top_menu_mobile_panel].visible == false,
        topmenu_mobile_fit();
    );
,
    set(layer[top_menu_bar].visible, true);
    set(layer[top_menu_mobile_btn].visible, false);
    topmenu_mobile_close();
    topmenu_mobile_fit();
);

set(_t, topmenu_dd_%1);
copy(_was_open, layer[get(_t)].visible);
topmenu_close_all();
if(_was_open == false,
    topmenu_show(get(_t));
);

set(layer[topmenu_click_catcher].visible, true);
set(layer[%1], visible=true, alpha=0, y=55);
tween(layer[%1].alpha|layer[%1].y, 1|70, 0.25, easeOutQuad);

if(layer[%1].visible,
    tween(layer[%1].alpha|layer[%1].y, 0|55, 0.20, easeInQuad, set(layer[%1].visible, false));
);

set(layer[topmenu_click_catcher].visible, false);
topmenu_hide(topmenu_dd_air);
topmenu_hide(topmenu_dd_af_small);
topmenu_hide(topmenu_dd_af_medium);
topmenu_hide(topmenu_dd_af_large);
topmenu_hide(topmenu_dd_tents);
topmenu_hide(topmenu_dd_public);

copy(_card_h, layer[tmm_card].pixelheight);
if(_card_h == 0, set(_card_h, 0); );
if(_card_h LT 200,
    mul(_card_h, stageheight, 0.9);
);
sub(_sh, _card_h, 50);
if(_sh LT 100, set(_sh, 100); );

if(layer[tmm_vp1].height != get(_sh),
    set(layer[tmm_vp1].height,           get(_sh));
    set(layer[tmm_vp2_air].height,       get(_sh));
    set(layer[tmm_vp2_af_small].height,  get(_sh));
    set(layer[tmm_vp2_af_medium].height, get(_sh));
    set(layer[tmm_vp2_af_large].height,  get(_sh));
    set(layer[tmm_vp2_tents].height,     get(_sh));
    set(layer[tmm_vp2_public].height,    get(_sh));
);

set(layer[top_menu_mobile_panel].visible, true);
set(layer[top_menu_mobile_panel].alpha, 0);
topmenu_mobile_back();
topmenu_mobile_fit();
tween(layer[top_menu_mobile_panel].alpha, 1, 0.22, easeOutQuad);

set(layer[tmm_lvl2_air].visible,       false);
set(layer[tmm_lvl2_af_small].visible,  false);
set(layer[tmm_lvl2_af_medium].visible, false);
set(layer[tmm_lvl2_af_large].visible,  false);
set(layer[tmm_lvl2_tents].visible,     false);
set(layer[tmm_lvl2_public].visible,    false);

set(layer[tmm_lvl1].visible, false);
topmenu_mobile_hide_items();

if(%1 == 'air',
    set(layer[tmm_lvl2_air].visible, true);
    set(layer[tmm_title].html, 'Барнхаус');
    layer[tmm_lvl2_air].scrolltocenter(0, 0, 0.0);
);
if(%1 == 'af_small',
    set(layer[tmm_lvl2_af_small].visible, true);
    set(layer[tmm_title].html, 'A-Frame малый');
    layer[tmm_lvl2_af_small].scrolltocenter(0, 0, 0.0);
);
if(%1 == 'af_medium',
    set(layer[tmm_lvl2_af_medium].visible, true);
    set(layer[tmm_title].html, 'A-Frame средний');
    layer[tmm_lvl2_af_medium].scrolltocenter(0, 0, 0.0);
);
if(%1 == 'af_large',
    set(layer[tmm_lvl2_af_large].visible, true);
    set(layer[tmm_title].html, 'A-Frame большой');
    layer[tmm_lvl2_af_large].scrolltocenter(0, 0, 0.0);
);
if(%1 == 'tents',
    set(layer[tmm_lvl2_tents].visible, true);
    set(layer[tmm_title].html, 'Шатры');
    layer[tmm_lvl2_tents].scrolltocenter(0, 0, 0.0);
);
if(%1 == 'public',
    set(layer[tmm_lvl2_public].visible, true);
    set(layer[tmm_title].html, 'Общественные места');
    layer[tmm_lvl2_public].scrolltocenter(0, 0, 0.0);
);

set(layer[tmm_back].visible, true);

topmenu_mobile_hide_items();
set(layer[tmm_lvl1].visible, true);
set(layer[tmm_back].visible, false);
set(layer[tmm_title].html, 'Помещения');
layer[tmm_lvl1].scrolltocenter(0, 0, 0.0);
